interface Request<Body = any> {
  body: Body;
}

function handlerFor(prefix: string): (request: Request, greeting: string) => string {
  return (request: Request, greeting: string) => prefix + greeting + request.body;
}

handlerFor("Hi ")({ body: "Ada" }, "hello ");

